package com.dentalcrm.appointment;
import com.dentalcrm.doctor.*; import com.dentalcrm.patient.*; import com.dentalcrm.user.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest; import java.time.OffsetDateTime; import static org.junit.jupiter.api.Assertions.*;
@DataJpaTest class AppointmentRepositoryTest {@Autowired AppointmentRepository appointments;@Autowired UserRepository users;@Autowired DoctorRepository doctors;@Autowired PatientRepository patients;
 @Test void detectsOverlappingButNotAdjacentAppointment(){User u=new User();u.setUsername("doc");u.setPasswordHash("hash");u.setFullName("Doc");u.setRole(Role.DOCTOR);users.save(u);Doctor d=new Doctor();d.setUser(u);doctors.save(d);Patient p=new Patient();p.setFullName("Patient");p.setPhone("123");patients.save(p);OffsetDateTime start=OffsetDateTime.parse("2030-01-01T10:00:00+06:00");Appointment a=new Appointment();a.setPatient(p);a.setDoctor(d);a.setStartTime(start);a.setEndTime(start.plusHours(1));a.setCreatedBy(u);appointments.saveAndFlush(a);assertTrue(appointments.hasConflict(d.getId(),start.plusMinutes(30),start.plusHours(2),null));assertFalse(appointments.hasConflict(d.getId(),start.plusHours(1),start.plusHours(2),null));}
}
